import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E3%82%BD%E3%83%BC%E3%82%B7%E3%83%A3%E3%83%AB%E3%83%A1%E3%83%87%E3%82%A3%E3%82%A2%E3%83%97%E3%83%AA%E3%82%BA%E3%83%A0.html","title":"【書籍】ソーシャルメディアプリズム","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.67,"words":801},"filePathRelative":"【書籍】ソーシャルメディアプリズム.md"}`),a={name:`【書籍】ソーシャルメディアプリズム.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】ソーシャルメディアプリズム" tabindex="-1"><a class="header-anchor" href="#【書籍】ソーシャルメディアプリズム"><span>【書籍】ソーシャルメディアプリズム</span></a></h1><p><a href="./書籍.html">書籍</a>, <a href="./インターネットリテラシー.html">インターネットリテラシー</a></p><ul><li><a href="https://amzn.to/4uLvUTI" target="_blank" rel="noopener noreferrer">amazon: ソーシャルメディア・プリズム――SNSはなぜヒトを過激にするのか? </a></li><li><a href="https://hb.afl.rakuten.co.jp/ichiba/517bc8c0.0747eabc.517bc8c1.b6411453/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Frakutenkobo-ebooks%2Fc6d16d03b7a93f53931cc9bf34c32f72%2F&amp;link_type=hybrid_url&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJoeWJyaWRfdXJsIiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MSwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="noopener noreferrer">kobo: ソーシャルメディア・プリズム――SNSはなぜヒトを過激にするのか? </a></li></ul><h2 id="購入とその動機-2026-03-20-金" tabindex="-1"><a class="header-anchor" href="#購入とその動機-2026-03-20-金"><span>購入とその動機: 2026-03-20 (金)</span></a></h2><p>SNSが分断に及ぼす影響に興味がある。だが、悪いという事をあげつらったり、悪くないという事をあげつらったりするのではなく、 実際の所はどうなのか？という事について、分かってる事と分かってない事をあげるようなのが読みたいな〜と思って、 適当にamazonで検索してそれっぽいサンプルを幾つか読んでいた所、この本はなかなか良さそうだったので購入。</p><h2 id="参考文献が豊富で興味深い-2026-03-21-土" tabindex="-1"><a class="header-anchor" href="#参考文献が豊富で興味深い-2026-03-21-土"><span>参考文献が豊富で興味深い 2026-03-21 (土)</span></a></h2><p>4章まで読んでみた。この本は割と薄いのかな。まだそんな読んだ気はしないが半分くらいに到達している。</p><p>この本は既存の研究から分かっている事をいろいろ自分なりの解釈で言うのだけれど、 その論拠になっている研究にかなり細かく参照がついている。</p><p>この、「自分なりの見解を語る」というのと、「けれど参照はちゃんとつける」という組み合わせがとても良いと思う。 既存研究を羅列するのでは無く、あくまで自分の言いたい事をちゃんと言っているので、読み物としてちゃんと主張があって興味深く読める。 けれど自分の言いたい事は元の研究からはずれている事もあるので、自分だけは真実を知っています、という感じで話すのでは無くて、 この辺の研究から自分はこう思っている、というのを明かしていて、その参考文献は興味の湧くものも多くある。</p><p>研究者が一般向けに書く本のお手本にしたくなるような書き方と思った。</p><h3 id="異なる政治信条に触れるのが逆効果になるのはsnsの問題では" tabindex="-1"><a class="header-anchor" href="#異なる政治信条に触れるのが逆効果になるのはsnsの問題では"><span>異なる政治信条に触れるのが逆効果になるのはSNSの問題では？</span></a></h3><p>内容的にはここまでは、エコーチェンバーの外の意見を無理やり流すようにすると、攻撃を受けたと解釈してより党派性が増してしまう、 という現象を確認して、それが人間のどういう性質から来ているのかをこれまでの心理学や社会学の研究から考える、という内容になっている。</p><p>党派性のアイデンティティーがここで言うような性質があるかは自分には良く分からない部分もあるが、 twitterで自分と対立する政治的信条のアカウントをフォローするのは逆効果だな、とは自分も思っていて、 最近はあまりフォローしないようになったので、結論には納得するものがある。</p><p>ただ党派性の異なる意見に対してこう反応するのが本質的だ、というよりは、twitterというのが自分と異なる意見にふれるのに良い手段では無い、という話だと思うんだよなぁ。 なんかこう、悪い所だけを切り取って見せられるので、かえって反発したくなるというか、説得されにくく提示されるというか。 だから自分と反対の意見を聞く事が良くないのではなく、良い聞き方もあるんじゃないか、という気はしている。</p><p>本書はこの後にそういう話が続くかもしれない雰囲気なので読み進めたいと思うが、 ここまでの内容では、本質的な人間の性質という内容に読める。</p><h3 id="過激派の描像は憂鬱になる話だなぁ" tabindex="-1"><a class="header-anchor" href="#過激派の描像は憂鬱になる話だなぁ"><span>過激派の描像は憂鬱になる話だなぁ</span></a></h3><p>民主党と共和党のそれぞれの対立派を激しく攻撃する人たちが、リアルでは生活に不満があって孤独で自分に価値が無いと思っている、みたいな話は、 みんなそうなのかな、と予想はしていた事ではあるけれど、実際にインタビューとかを見ると憂鬱になるものがあるなぁ。</p><p>カルト的な集団としてお互いを監視しあって依存するようになる、みたいな話も、いかにもありそうだが困ったものだな…</p><p>SNSをなくせばいいのか？というのは微妙な所だが、SNSはこういうのを増幅してしまう気はするな。</p><p>そして穏健派はリア充なのでリアルで失うものが多いからSNSではあまり政治発言はしない、だからSNS上は過激派ばかりになる、というのは、 めちゃありそうな話だが救いが無いな…</p><h2 id="参考文献がちゃんと記されてるので、素晴らしい本だった-2026-03-26-木" tabindex="-1"><a class="header-anchor" href="#参考文献がちゃんと記されてるので、素晴らしい本だった-2026-03-26-木"><span>参考文献がちゃんと記されてるので、素晴らしい本だった 2026-03-26 (木)</span></a></h2><p>読み終わったので感想。まずは上記の感想の続きの後半の感想から。</p><p>SNSをやめればいいのか？という話は、やめてもすぐ戻ってくるというデータを元にやめる事は出来ないと結論づけているが、 それはあまり説得力は感じなかった。 やめれば解決する問題なら、単に違法にしたりやめる方法を模索したりいろいろやりようはある気もする。</p><p>ただそうした事も含めて、すべての主張に根拠をちゃんとしめしていて、参考文献もいちいちつけている。 これは素晴らしい。 以前以下のブログを書いた時に期待したのは、こういう本だったと思う。＞<a href="https://karino2.github.io/2025/06/25/SNS_phsycology_study_book.html" target="_blank" rel="noopener noreferrer">SNSの心理などに対する影響の、ちゃんとした研究が紹介された本とか無いものか？ - なーんだ、ただの水たまりじゃないか</a></p><p>本当の所は良く分からない所であるからこそ、ちゃんと根拠を示すのは大切だよなぁ。 実際興味が湧いた論文や本も幾つかあったので、ダウンロードしたりサンプルを送ったりしてある。あとで読んでいきたい。</p><p>最後の実験の詳細は読んでない。また、終盤の自分たちで作った匿名SNSの話は、自分で本気でサービス当てる気がない奴がこういうの語ってもなぁ、と白ける部分はあった。</p><p>ただ最後まで読みはしたので、本としては成立していたと思う。</p><h3 id="全体的な感想" tabindex="-1"><a class="header-anchor" href="#全体的な感想"><span>全体的な感想</span></a></h3><p>思ったよりは短めの本だった気がする。</p><p>全体としては、驚きの結論はそんなに多くは無くて、極端な意見がSNSでは広まりがちで、大多数はそんなに極端じゃない、けれどそれを誤解してしまう、みたいな話。 まぁたぶんそうなんじゃないかな、と思う事なので、別段疑わしいという気持ちは沸かない。 どのくらい正しいのかは良く分からない部分もあるが。 でも実際自分が口をつぐむ理由を振り返っても本書の話と整合的なので、割と説得はされた。</p><p>実際に極端な発言をしている人たちのバックグラウンドの話が結構あって、そこは興味があった事なので、本書を読んで良かった、という気になった。 ただ、孤独で貧しい中年、みたいないかにもなステレオタイプそのまんまで、 ちょっと憂鬱な気分にはなる。 一方恵まれた人たちは失うものが多いのでSNS上で政治の話はしない（意訳）、というのを読むと、 SNSで暴れるくらいは許してやってもいいんじゃないか、という気も湧いてくる。</p><p>実際はそこまで分断は進んでいない、というのは、そういう可能性はありそうだな、 という気はもともとしている主張ではあったけれど、 実際の所はどうなのか良く分からない部分だったので、 実際に証拠をいろいろ上げて解説しているのは「なるほど、そうなのか」という納得はあった。</p><p>SNSは有害だ、という本も、有害というのは嘘だ、という本も、どちらもあらかじめ結論が自分の中にあって、それを補強する研究などを我田引水するだけで、あまり学びが無い事が多いが、 本書はそういう事は無かった。 本書の著者も最初から結論があるような所はあるけれど、 その根拠が割とちゃんと示されているので、著者の主張に同意しない人でも役に立つ内容となっているし、 どのくらい主張の説得力があるのかも各自が判断出来るようになっている。 そうそう、ちゃんとした研究者はこういう本の書き方をしないといけないよな、と思わせる、手本にしたくなるような本だ。</p><p>そういう訳で、この手の本にしては読んでいて我慢ならない感じにもならずに最後まで読めて、 いろいろ既存の研究を知るのに良い本だと思った。 SNSが有害かどうかに関心がある人にはおすすめ出来る。</p>`,34)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};